defined('ABSPATH') || exit;
function ed_hero_v2_media(){ $asset=json_decode(file_get_contents(get_theme_file_path('/assets/patterns/homepage-hero-v2.json')),true);return ed_pattern_media($asset['path'],$asset['alt']); }
/** Change only the hero cover, preserving other sections and editorial changes. */
function ed_update_homepage_hero($content,$strict=false){
 $media=ed_hero_v2_media();if(!$media['id']){if($strict)throw new RuntimeException('Upload main_hero_photo_v2.jpg before applying the hero update.');return $content;}
 $original=parse_blocks(ed_homepage_pattern_content());$old=$original[0]['attrs']['url']??'';$uploads=wp_upload_dir();$legacy=trailingslashit($uploads['baseurl']).'2026/10/main_hero_photo.jpg';$blocks=parse_blocks($content);$count=0;
 $walk=function(&$blocks)use(&$walk,&$count,$media,$old,$legacy,$strict){foreach($blocks as &$b){if(($b['blockName']??'')==='core/cover'&&in_array('ed-hero',explode(' ',$b['attrs']['className']??''),true)){$count++;$url=$b['attrs']['url']??'';if($strict&&!in_array($url,[$old,$legacy,$media['url']],true))throw new RuntimeException('The hero image was independently changed; review it before migration.');$oldId=$b['attrs']['id']??0;$oldAlt=$b['attrs']['alt']??'';$b['attrs']['url']=$media['url'];$b['attrs']['id']=$media['id'];$b['attrs']['alt']=$media['alt'];$patch=function($html)use($url,$media,$oldId,$oldAlt){$html=str_replace(['src="'.esc_url($url).'"','alt="'.esc_attr($oldAlt).'"'],['src="'.esc_url($media['url']).'"','alt="'.esc_attr($media['alt']).'"'],$html);if($oldId)$html=str_replace('wp-image-'.$oldId,'wp-image-'.$media['id'],$html);else $html=str_replace('class="wp-block-cover__image-background"','class="wp-block-cover__image-background wp-image-'.$media['id'].'"',$html);return $html;};$b['innerHTML']=$patch($b['innerHTML']);foreach($b['innerContent'] as &$piece)if(is_string($piece))$piece=$patch($piece);unset($piece);}if(!empty($b['innerBlocks']))$walk($b['innerBlocks']);}};$walk($blocks);if($strict&&$count!==1)throw new RuntimeException('Expected exactly one homepage hero.');return serialize_blocks($blocks);
}
function ed_current_homepage_pattern_content(){return ed_update_homepage_hero(ed_homepage_pattern_content());}
